def positive_int(value: str) -> int:
    if not re.fullmatch(r"[0-9]+", value):
        raise argparse.ArgumentTypeError("must be an integer >= 1")
    digits = value.lstrip("0")
    if not digits:
        raise argparse.ArgumentTypeError("must be an integer >= 1")
    max_index = str(sys.maxsize)
    if len(digits) > len(max_index) or (
        len(digits) == len(max_index) and digits > max_index
    ):
        return sys.maxsize
    return int(digits)

